//! The two scene description files.
//!
//! - `scene/lighting.json` belongs to this project and is edited by hand: the world color, the
//!   presentation cameras, the reflection probe boxes and the lights. Coordinates are Bevy's
//!   (Y-up, metres). Light power and colors use Blender's units (see `units.rs`).
//! - `assets/materials.json` is generated by `tools/export_blend.py`: one PBR definition per
//!   Blender material.

use bevy::prelude::*;
use serde::Deserialize;

#[derive(Deserialize)]
pub struct Lighting {
    pub world: World,
    pub cameras: Vec<CameraShot>,
    pub probes: Vec<ProbeBox>,
    pub lights: Vec<Light>,
}

#[derive(Deserialize)]
pub struct World {
    /// The color rays see when they leave the hall, Blender radiance.
    pub background: [f32; 3],
    pub background_strength: f32,
    /// Blender's world volume: a principled volume with this scattering color and density
    /// (per metre) and a Henyey-Greenstein anisotropy. Only the probe bake uses it; the app
    /// renders no haze.
    pub haze_color: [f32; 3],
    pub haze_density: f32,
    pub haze_anisotropy: f32,
}

#[derive(Deserialize)]
pub struct Light {
    pub name: String,
    /// "point" or "area".
    pub kind: String,
    pub watts: f32,
    /// Linear color. It includes Blender's color temperature: Blender multiplies the light
    /// color by the blackbody color of `temperature`, scaled to a luminance of 1. A 2300 K
    /// candle is (2.224, 0.728, 0.089).
    pub color: [f32; 3],
    /// Blender's glossy ray visibility. Only glossy lights show highlights in the app.
    pub glossy: bool,
    pub position: [f32; 3],
    /// Point lights: the radius of the light sphere.
    #[serde(default)]
    pub radius: f32,
    /// Area lights: orientation (x, y, z, w). The panel emits along its local −Z.
    #[serde(default = "identity")]
    pub rotation: [f32; 4],
    #[serde(default)]
    pub width: f32,
    #[serde(default)]
    pub height: f32,
    /// Area lights: beam angle in radians; π is a plain Lambertian panel.
    #[serde(default = "lambertian")]
    pub spread: f32,
}

fn identity() -> [f32; 4] {
    [0.0, 0.0, 0.0, 1.0]
}

fn lambertian() -> f32 {
    std::f32::consts::PI
}

impl Light {
    pub fn rotation(&self) -> Quat {
        Quat::from_array(self.rotation).normalize()
    }
}

#[derive(Deserialize)]
pub struct CameraShot {
    pub name: String,
    pub lens: f32,
    pub sensor_width: f32,
    /// Blender's view exposure in stops.
    pub exposure: f32,
    pub resolution: [u32; 2],
    /// Blender lens shift (x, y) in units of the frame width.
    pub shift: [f32; 2],
    pub position: [f32; 3],
    /// The camera looks along its local −Z with local +Y up.
    pub rotation: [f32; 4],
}

impl CameraShot {
    pub fn transform(&self) -> Transform {
        Transform::from_translation(Vec3::from(self.position)).with_rotation(Quat::from_array(self.rotation).normalize())
    }
}

/// A reflection probe: a cubemap captured at the box center, parallax-corrected to the box.
#[derive(Deserialize)]
pub struct ProbeBox {
    pub center: [f32; 3],
    pub size: [f32; 3],
}

/// One Blender material baked into PBR maps. Texture paths are relative to `assets/`.
#[derive(Deserialize, Default)]
#[serde(default)]
pub struct MaterialDef {
    pub name: String,
    pub base: Option<String>,
    pub mr: Option<String>,
    pub normal: Option<String>,
    pub emissive_map: Option<String>,
    /// The base color texture doubles as the emissive texture.
    pub emissive_texture: bool,
    pub color: Option<[f32; 3]>,
    pub emissive: Option<[f32; 3]>,
    pub emissive_strength: f32,
    pub roughness: Option<f32>,
    pub metallic: Option<f32>,
    pub reflectance: Option<f32>,
    pub clearcoat: f32,
    pub clearcoat_roughness: f32,
    pub transmission: f32,
    /// Transmission that only the baker applies. The app renders the crystal opaque.
    pub bake_transmission: f32,
    pub ior: Option<f32>,
    /// Blender's Specular IOR Level: 0.5 keeps the F0 of the IOR, 1.0 doubles it.
    pub specular_ior_level: Option<f32>,
    pub alpha_mask: Option<f32>,
    pub double_sided: bool,
    pub uv_scale: Option<[f32; 2]>,
    pub uv_offset: Option<[f32; 2]>,
}

fn read(path: &str, hint: &str) -> String {
    std::fs::read_to_string(path).unwrap_or_else(|e| panic!("{path}: {e}. {hint}"))
}

pub fn load_lighting() -> Lighting {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/scene/lighting.json");
    serde_json::from_str(&read(path, "It is under version control.")).expect("scene/lighting.json")
}

pub fn load_materials() -> Vec<MaterialDef> {
    let path = concat!(env!("CARGO_MANIFEST_DIR"), "/assets/materials.json");
    serde_json::from_str(&read(path, "Run tools/export_blend.py first.")).expect("materials.json")
}
